<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Category,Service};
class BookingTest extends TestCase{use RefreshDatabase;public function test_customer_can_create_booking():void{$c=User::create(['name'=>'C','email'=>'c@x.test','password'=>'password','role'=>'customer']);$p=User::create(['name'=>'P','email'=>'p@x.test','password'=>'password','role'=>'provider']);$cat=Category::create(['name'=>'Cleaning','slug'=>'cleaning','is_active'=>true]);$s=Service::create(['category_id'=>$cat->id,'provider_id'=>$p->id,'name'=>'Clean','slug'=>'clean','price'=>500,'duration'=>'2 hours','is_active'=>true]);$this->actingAs($c)->post('/bookings',['service_id'=>$s->id,'booking_date'=>now()->addDay()->format('Y-m-d'),'booking_time'=>'14:00','address'=>'Surat'])->assertRedirect();$this->assertDatabaseHas('bookings',['customer_id'=>$c->id,'service_id'=>$s->id,'status'=>'pending']);}}
